  "faq.q3": "출금은 어떻게 작동하나요?",
  "faq.a3": "FaucetPay를 통해 즉시 출금을 처리합니다. FaucetPay 계정을 연결하고 언제든지 수익을 출금하세요.",
  "faq.q4": "최소 출금액이 있나요?",
  "faq.a4": "네, 최소 출금액은 10,000 사토시입니다. 이는 효율적인 거래 처리를 보장합니다.",
  "faq.q5": "추천 시스템은 어떻게 작동하나요?",
  "faq.a5": "3단계 추천 시스템을 통해 직접 추천 10%, 추천인의 추천 5%, 3단계 추천 2%를 얻을 수 있습니다.",
  "faq.q6": "Faucero는 안전한가요?",
  "faq.a6": "네! 계정을 보호하기 위해 2FA, 암호화된 데이터 저장 및 고급 사기 탐지를 포함한 기업급 보안을 사용합니다.",
  "faq.q7": "연속 보너스는 어떻게 작동하나요?",
  "faq.a7": "연속 보너스는 연속적인 일일 청구 횟수에 따라 증가합니다. 수입을 극대화하기 위해 연속 기록을 유지하세요.",
  "faq.q8": "신분증 확인이 필요한가요?",
